### Complete Capstone Project Sketch
Upload this complete firmware sketch to your Arduino Uno to activate the high-speed Monster Security Gate!

```cpp
#include <SPI.h>
#include <MFRC522.h>

// Hardware Pin Assignments
const int CS_MATRIX = 10; // MAX7219 Chip Select
const int CS_RFID   = 8;  // RC522 Chip Select (SDA)
const int RST_RFID  = 9;  // RC522 Reset

MFRC522 rfid(CS_RFID, RST_RFID);

// State Machine Definitions
enum GateState { STATE_IDLE, STATE_GRANTED, STATE_DENIED };
GateState currentState = STATE_IDLE;
unsigned long stateTimer = 0;

// Animation Variables for Idle Radar
unsigned long lastAnimTime = 0;
int radarCol = 0;
int radarDir = 1;

// Graphic Bitmaps (8x8)
const byte iconCheckmark[8] = {
  B00000000, B00000001, B00000011, B00010110,
  B00111100, B00111000, B00110000, B00000000
};

const byte iconCross[8] = {
  B10000001, B01000010, B00100100, B00011000,
  B00011000, B00100100, B01000010, B10000001
};

// Low-level MAX7219 register writer
void writeMatrix(byte reg, byte data) {
  digitalWrite(CS_RFID, HIGH);   // Isolate RFID
  digitalWrite(CS_MATRIX, LOW);  // Assert Matrix CS
  SPI.transfer(reg);
  SPI.transfer(data);
  digitalWrite(CS_MATRIX, HIGH); // Latch data
}

void drawBitmap(const byte bitmap[8]) {
  for (byte i = 0; i < 8; i++) {
    writeMatrix(i + 1, bitmap[i]);
  }
}

void clearMatrix() {
  for (byte i = 1; i <= 8; i++) {
    writeMatrix(i, 0x00);
  }
}

void setup() {
  Serial.begin(9600);
  while (!Serial);

  // Initialize CS lines
  pinMode(CS_MATRIX, OUTPUT);
  pinMode(CS_RFID, OUTPUT);
  digitalWrite(CS_MATRIX, HIGH);
  digitalWrite(CS_RFID, HIGH);

  // Initialize SPI bus
  SPI.begin();

  // Initialize MAX7219
  writeMatrix(0x0C, 0x01); // Wake from shutdown
  writeMatrix(0x09, 0x00); // Raw matrix mode
  writeMatrix(0x0B, 0x07); // Scan all 8 rows
  writeMatrix(0x0A, 0x04); // Intensity
  clearMatrix();

  // Initialize RFID
  rfid.PCD_Init();
  Serial.println("MONSTER LAB: High-Speed Access Gate Online!");
}

void loop() {
  unsigned long now = millis();

  if (currentState == STATE_IDLE) {
    // 1. Update radar animation every 60ms
    if (now - lastAnimTime > 60) {
      lastAnimTime = now;
      byte colMask = (1 << radarCol);
      for (byte r = 1; r <= 8; r++) {
        writeMatrix(r, colMask);
      }
      radarCol += radarDir;
      if (radarCol >= 7 || radarCol <= 0) radarDir = -radarDir;
    }

    // 2. Poll for RFID card
    if (rfid.PICC_IsNewCardPresent() && rfid.PICC_ReadCardSerial()) {
      Serial.print("Card Detected! UID: ");
      for (byte i = 0; i < rfid.uid.size; i++) {
        Serial.print(rfid.uid.uidByte[i], HEX);
        Serial.print(" ");
      }
      Serial.println();

      // Simple authorized check: tag first byte == 0xDE or 0x4B
      bool isAuthorized = (rfid.uid.uidByte[0] == 0xDE || rfid.uid.uidByte[0] == 0x4B);

      if (isAuthorized) {
        Serial.println("ACCESS GRANTED! Welcome, Monster Engineer!");
        drawBitmap(iconCheckmark);
        currentState = STATE_GRANTED;
      } else {
        Serial.println("ACCESS DENIED! Unauthorized tag detected!");
        drawBitmap(iconCross);
        currentState = STATE_DENIED;
      }
      stateTimer = now;
      rfid.PICC_HaltA();
    }
  }
  else if (currentState == STATE_GRANTED || currentState == STATE_DENIED) {
    // Hold feedback icon for 2 seconds, then return to radar
    if (now - stateTimer > 2000) {
      clearMatrix();
      currentState = STATE_IDLE;
      Serial.println("Terminal returned to IDLE radar mode.");
    }
  }
}
```

### Engineering Review:
- Both peripherals share Pins 11 (MOSI) and 13 (SCK) flawlessly.
- Notice how clean the Serial Monitor output is and how quickly the MAX7219 switches from the radar animation to the checkmark icon when a card is tapped!
